def find(parent, x):
    while parent[x] != x:
        parent[x] = parent[parent[x]]
        x = parent[x]
    return x


def union(parent, rank, a, b):
    a, b = find(parent, a), find(parent, b)
    if a == b:
        return False
    if rank[a] < rank[b]:
        a, b = b, a
    parent[b] = a
    if rank[a] == rank[b]:
        rank[a] += 1
    return True


def kruskal(n, edges):              # edges: (u, v, weight)
    parent = list(range(n))
    rank = [0] * n
    edges.sort(key=lambda e: e[2])
    total = count = 0
    for u, v, w in edges:
        if union(parent, rank, u, v):
            total += w
            count += 1
            print(u, "-", v, ":", w)
            if count == n - 1:
                break
    return total


